{"path":"dist/auth/oauth/radius.js","physical_source":"dist/auth/oauth/radius.js","start":7286,"end":8031,"line":195,"column":13,"physical_line":195,"raw_source":"catch (error) {
                if (!(error instanceof OAuthResponseError)) {
                    throw error;
                }
                switch (error.oauthError) {
                    case "authorization_pending":
                        return { status: "pending" };
                    case "slow_down":
                        return { status: "slow_down" };
                    case "expired_token":
                        return { status: "failed", message: "Device authorization expired." };
                    case "access_denied":
                        return { status: "failed", message: "Device authorization was denied." };
                    default:
                        throw error;
                }
            }"}

